-- ============================================================
-- ALLOCATE payments to installments (oldest-first) for ACTIVE sales
-- Sets installments.amount_paid / status and links payment->installment.
-- ============================================================
DO $alloc$
DECLARE
  v_company uuid; r_sale record; r_pay record; r_inst record; v_remain numeric;
BEGIN
  SELECT id INTO v_company FROM companies WHERE company_name ILIKE 'Fourteen Group%' LIMIT 1;
  FOR r_sale IN SELECT s.id FROM sales s WHERE s.company_id=v_company AND s.status='active' LOOP
    -- reset
    UPDATE installments SET amount_paid=0, status='pending', paid_at=NULL WHERE sale_id=r_sale.id;
    FOR r_pay IN SELECT id, amount, payment_date FROM payments WHERE sale_id=r_sale.id ORDER BY payment_date, created_at LOOP
      v_remain := r_pay.amount;
      FOR r_inst IN SELECT id, amount_due, amount_paid FROM installments
                    WHERE sale_id=r_sale.id AND amount_paid < amount_due
                    ORDER BY installment_number LOOP
        EXIT WHEN v_remain <= 0;
        DECLARE v_need numeric := r_inst.amount_due - r_inst.amount_paid;
                v_apply numeric := LEAST(v_need, v_remain);
        BEGIN
          UPDATE installments
            SET amount_paid = amount_paid + v_apply,
                status = CASE WHEN amount_paid + v_apply >= amount_due THEN 'paid' ELSE 'partial' END,
                paid_at = CASE WHEN amount_paid + v_apply >= amount_due THEN now() ELSE paid_at END,
                related_payment_id = r_pay.id
            WHERE id = r_inst.id;
          v_remain := v_remain - v_apply;
        END;
      END LOOP;
    END LOOP;
  END LOOP;
  RAISE NOTICE 'Allocation done';
END $alloc$;

-- ============================================================
-- VERIFICATION (review these BEFORE COMMIT). Expected values in comments.
-- ============================================================
WITH c AS (SELECT id FROM companies WHERE company_name ILIKE 'Fourteen Group%' LIMIT 1),
     p AS (SELECT id FROM projects WHERE project_name ILIKE 'KHUSHAL BAGH HEIGHTS' LIMIT 1)
SELECT
  (SELECT count(*) FROM units u,c,p WHERE u.company_id=c.id AND u.project_id=p.id)                AS units_total,         -- expect 260
  (SELECT count(*) FROM sales s,c,p WHERE s.company_id=c.id AND s.project_id=p.id AND s.status='active')   AS sales_active,  -- expect 182
  (SELECT count(*) FROM sales s,c,p WHERE s.company_id=c.id AND s.project_id=p.id AND s.status='cancelled')AS sales_cancelled, -- expect 49
  (SELECT count(DISTINCT client_id) FROM sales s,c,p WHERE s.company_id=c.id AND s.project_id=p.id)        AS clients_total, -- expect ~231
  (SELECT count(*) FROM installments i,c WHERE i.company_id=c.id)                                  AS installments_total,
  (SELECT count(*) FROM payments pm,c WHERE pm.company_id=c.id)                                    AS payments_total,      -- expect ~1773
  (SELECT to_char(coalesce(sum(amount),0),'FM999,999,999,999') FROM payments pm,c WHERE pm.company_id=c.id) AS total_received;

-- Per active sale: received vs expected (spot-check). Should match Client Record.
