-- NOTE: transaction left OPEN intentionally. Review above, then COMMIT or ROLLBACK.

ALTER TABLE payments ENABLE TRIGGER trg_payment_health;

-- ============================================================
-- VERIFICATION GUARD: RAISE NOTICE counts, RAISE EXCEPTION on mismatch -> auto-rollback; else COMMIT
-- ============================================================
DO $verify$
DECLARE
  c_id uuid; p_id uuid;
  v_units bigint; v_active bigint; v_cancelled bigint; v_clients bigint;
  v_installs bigint; v_payments bigint; v_total text;
BEGIN
  SELECT id INTO c_id FROM companies WHERE company_name ILIKE 'Fourteen Group%' LIMIT 1;
  SELECT id INTO p_id FROM projects  WHERE project_name ILIKE 'KHUSHAL BAGH HEIGHTS' LIMIT 1;
  SELECT count(*)                  INTO v_units     FROM units        WHERE company_id=c_id AND project_id=p_id;
  SELECT count(*)                  INTO v_active    FROM sales        WHERE company_id=c_id AND project_id=p_id AND status='active';
  SELECT count(*)                  INTO v_cancelled FROM sales        WHERE company_id=c_id AND project_id=p_id AND status='cancelled';
  SELECT count(DISTINCT client_id) INTO v_clients   FROM sales        WHERE company_id=c_id AND project_id=p_id;
  SELECT count(*)                  INTO v_installs  FROM installments WHERE company_id=c_id;
  SELECT count(*)                  INTO v_payments  FROM payments     WHERE company_id=c_id;
  SELECT to_char(coalesce(sum(amount),0),'FM999,999,999,999') INTO v_total FROM payments WHERE company_id=c_id;
  RAISE NOTICE 'VERIFY: units=% | active=% | cancelled=% | clients=% | installments=% | payments=% | total_received=%',
    v_units, v_active, v_cancelled, v_clients, v_installs, v_payments, v_total;
  IF v_units     <> 260                     THEN RAISE EXCEPTION 'COUNT MISMATCH: units=% (expected 260)',      v_units;     END IF;
  IF v_active    <> 182                     THEN RAISE EXCEPTION 'COUNT MISMATCH: active=% (expected 182)',     v_active;    END IF;
  IF v_cancelled <>  49                     THEN RAISE EXCEPTION 'COUNT MISMATCH: cancelled=% (expected 49)',   v_cancelled; END IF;
  IF v_clients < 180 OR v_clients > 240     THEN RAISE EXCEPTION 'COUNT MISMATCH: clients=% (expected 191 post-dedup)', v_clients; END IF;
  IF v_payments < 1765 OR v_payments > 1781 THEN RAISE EXCEPTION 'COUNT MISMATCH: payments=% (expected ~1773)',v_payments;  END IF;
  RAISE NOTICE 'ALL COUNTS OK -> COMMITTING';
END $verify$;

COMMIT;